<?php
    require_once(dirname(__FILE__) . "/GetPlaceHandler.php");

    class UpdatePlaceHandler extends Handler {
        public function handle($input, $roles) {
            global $placeService, $databaseProvider;

            $response = (new GetPlaceHandler())
                ->handle(array(
                    "placeId" => $input["placeId"]), $roles);                    
            if ($response["code"] != 200) {
                return $response;
            }

            if (isset($input["mainHighlightId"])) {
                $placeService->updatePlaceMainHighlight($input["placeId"], $input["mainHighlightId"]);
            }

            if (isset($input["latitude"]) && isset($input["longitude"])) {
                $placeService->updatePlaceLocation($input["placeId"], $input["latitude"], $input["longitude"]);
            }

            if (array_key_exists("excerpt", $input)) {
                $placeService->updatePlaceExcerpt($input["placeId"], $input["excerpt"]);
            }

            if (isset($input["name"])) {
                $placeService->updatePlaceName($input["placeId"], $input["name"]);
            }
            
            $databaseProvider->materializeViews();
            return (new GetPlaceHandler())
                ->handle(array(
                    "placeId" => $input["placeId"]), $roles);
        }

        public function getRequiredRole() {
            return "ADMIN";
        }
        
        public function isProtected() {
            return TRUE;
        }

        public function getTag() {
            return "Places";
        }

        public function getPath() {
            return "/places/{placeId}";
        }

        public function getParameters() {
            return array(
                $this->createPathParameter("placeId", "integer", 2507));
        }

        public function getMethod() {
            return "PATCH";
        }
        
        public function getShortDescription() {
            return "Update a place with the specified identifier";
        }
        
        public function getLongDescription() {
            return "Updates a place with the specified identifier.";
        }
        
        public function getRequestExamples() {
            return array(
                $this->createRequestExample("Update place name", '{"name":"Praha"}'),
                $this->createRequestExample("Update place location", '{"latitude":50.0755381,"longitude":14.4378005}'),
                $this->createRequestExample("Update place main highlight", '{"mainHighlightId":1}'),
                $this->createRequestExample("Update place excerpt", '{"excerpt":"Praha, srdce Evropy, je město s duší, kde se historie prolíná s moderním životem. Procházet se po dlážděných uličkách Starého Města a obdivovat gotické katedrály, ztratit se v labyrintu uliček Židovského města, nebo se nechat unést na vltavské hladině pod Karlovým mostem - to vše je Praha. Atmosféra tajemství a elegance se line ulicemi, kde se potkávají barvité uliční umělci s kavárenskými poety a vřelá atmosféra hostinských domů s moderním pulsem života. Praha je město, které okouzlí každého, ať už milujete umění, historii, nebo jen klidné procházky s kávou v ruce.  Ať už se budete toulat po královských zahradách, ochutnávat pivo v tradičních pivovarech, nebo se ponoříte do nočního života, Praha vám nabídne něco, co jinde nenajdete. Neváhejte a prožijte svůj vlastní pražský příběh."}'));
        }

